<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from "vue";
import { api, dateLabel, download, labels, newColumn, operations, useAction, type Config, type Template, type MaintenanceField } from "./api";
const props = defineProps<{id?: string; canManage: boolean}>();
const emit = defineEmits<{open: [id: string]; back: []; dirty: [value: boolean]}>();
const {busy, error, message, run} = useAction();
const items = ref<Template[]>([]), selected = ref<Template>(), config = ref<Config>(), baseline = ref('');
const confirmed = ref(false), instructions = ref(''), uploadName = ref(''), purpose = ref('output'), file = ref<File>(), sample = ref<File>();
const tab = ref('fields'), showImport = ref(false), advanced = ref(''), advancedOpen = ref(false);
let timer: number | undefined;
const locked = computed(() => !props.canManage || selected.value?.status === 'published' || ['processing','learning'].includes(selected.value?.status || ''));
const dirty = computed(() => !!config.value && JSON.stringify(config.value) !== baseline.value || !!selected.value && confirmed.value !== selected.value.payload.confirmed);
watch(dirty, value => emit('dirty', value));
function accept(value: Template) { selected.value = value; config.value = structuredClone(value.payload.config); baseline.value = JSON.stringify(config.value); confirmed.value = value.payload.confirmed; }
async function load() {
  if (props.id) accept(await api<Template>(`/workflow-templates/${props.id}`));
  else items.value = (await api<{items: Template[]}>('/workflow-templates')).items;
}
async function create(source?: string) {
  const item = await api<Template>('/workflow-templates', 'POST', {source_id: source, name: '新商品业务流程'}); emit('open', item.id);
}
async function upload() {
  if (!file.value) throw new Error('请选择 Excel 模板。');
  const form = new FormData(); form.append('excel_file', file.value); form.append('name', uploadName.value || file.value.name.replace(/\.xlsx$/i, '')); form.append('purpose', purpose.value);
  const item = await api<Template>('/workflow-templates/import', 'POST', form); emit('open', item.id);
}
async function save() {
  if (!selected.value || !config.value) return;
  accept(await api<Template>(`/workflow-templates/${selected.value.id}`, 'PUT', {base_revision: selected.value.revision, config: config.value, confirmed: confirmed.value}));
  message.value = '草稿已保存。';
}
async function learn() {
  if (dirty.value) await save();
  accept(await api<Template>(`/workflow-templates/${props.id}/learn`, 'POST', {base_revision: selected.value?.revision, instructions: instructions.value}));
}
async function trial() {
  if (dirty.value) await save();
  const form = new FormData(); form.append('base_revision', String(selected.value?.revision)); if (sample.value) form.append('sample_file', sample.value);
  try { accept(await api<Template>(`/workflow-templates/${props.id}/trial`, 'POST', form)); tab.value = 'test'; }
  catch (error) { accept(await api<Template>(`/workflow-templates/${props.id}`)); throw error; }
}
async function publish() {
  if (dirty.value) await save();
  accept(await api<Template>(`/workflow-templates/${props.id}/publish`, 'POST', {base_revision: selected.value?.revision})); message.value = '模板已发布，可在新建任务中选用。';
}
function addField() {
  const field: MaintenanceField = {rule: {name: `custom_${Date.now()}`, title: '新字段', type: 'string', required: false, aliases: [], enum_values: [], validation: {unique: false}}, editable: true, default: null};
  config.value?.fields.push(field);
}
function applyAdvanced() {
  try { config.value = JSON.parse(advanced.value); advancedOpen.value = false; } catch { error.value = 'JSON 格式无效，请检查后再应用。'; }
}
function split(value: string) { return value.split(/[,，]/).map(s => s.trim()).filter(Boolean); }
onMounted(() => { void run(load); timer = window.setInterval(() => { if (!busy.value && ['processing','learning'].includes(selected.value?.status || '')) void load().catch(cause => { error.value = cause.message; }); }, 1500); });
onUnmounted(() => { window.clearInterval(timer); emit('dirty', false); });
</script>

<template>
  <button v-if="id" class="btn text breadcrumb" @click="emit('back')">← 返回模板中心</button>
  <div v-if="error" class="notice error" role="alert">{{ error }}</div><div v-if="message" class="notice success" role="status">{{ message }}</div>
  <template v-if="!id">
    <div class="page-heading"><div><p class="kicker">把处理经验，保存为可重复使用的流程</p><h1>模板中心</h1><p class="subtle">配置导入、维护和输出规则。确认一次，后续任务按版本执行。</p></div><div v-if="canManage" class="toolbar"><button class="btn" :disabled="busy" @click="run(() => create())">新建流程</button><button class="btn primary" @click="showImport = !showImport">↑ 导入 Excel 模板</button></div></div>
    <section v-if="showImport" class="card"><h2>从 Excel 学习模板结构</h2><div class="form-grid"><label>流程名称<input v-model="uploadName" placeholder="例如：灯具商品导入流程" /></label><label>这份文件的用途<select v-model="purpose"><option value="output">最终输出表模板</option><option value="maintenance">标准维护表模板</option><option value="import">原始数据样例</option></select></label></div><label class="upload-box"><span class="upload-symbol">↑</span><strong>{{ file?.name || '选择 Excel 模板' }}</strong><span>可上传空白模板或带少量示例的数据表</span><input type="file" accept=".xlsx" @change="file = ($event.target as HTMLInputElement).files?.[0]" /></label><div class="form-footer"><p class="subtle">先解析结构，再按需使用 AI 补充建议。未发布的草稿不会用于任务。</p><button class="btn primary" :disabled="busy || !file" @click="run(upload)">解析模板 →</button></div></section>
    <div class="template-grid"><article v-for="item in items" :key="item.id" class="card template-card"><div class="section-heading"><span class="template-icon">▦</span><span class="badge" :class="item.status">{{ labels[item.status] }}</span></div><h2>{{ item.payload.config.name }}</h2><p class="subtle">{{ item.payload.config.description || '自定义商品处理流程' }}</p><div class="template-counts"><span><strong>{{ item.payload.config.fields.length }}</strong> 维护字段</span><span><strong>{{ item.payload.config.outputs.length }}</strong> 输出文件</span></div><div class="card-footer"><span class="subtle">V{{ item.payload.version }} · {{ dateLabel(item.updated_at) }}</span><button class="btn text" @click="emit('open', item.id)">{{ item.status === 'published' ? '查看模板' : '继续配置' }} →</button></div></article></div>
  </template>
  <template v-else-if="selected && config">
    <div class="page-heading"><div><h1>{{ config.name }}</h1><p class="subtle">模板 V{{ selected.payload.version }} · {{ selected.status === 'published' ? '已发布版本保持不变，修改会创建新版本。' : '完善规则，试运行通过后发布。' }}</p></div><div class="toolbar"><span class="badge" :class="selected.status">{{ labels[selected.status] }}</span><button v-if="selected.status === 'published' && canManage" class="btn primary" :disabled="busy" @click="run(() => create(selected!.id))">创建新版本</button></div></div>
    <div v-if="selected.payload.error" class="notice error">{{ selected.payload.error }}</div>
    <section v-if="['processing','learning'].includes(selected.status)" class="card empty-state"><div class="spinner"></div><h2>{{ selected.status === 'learning' ? 'AI 正在整理规则建议' : '正在解析 Excel 结构' }}</h2><p>完成后请检查字段映射、类型和业务规则。</p></section>
    <template v-else>
      <section class="card compact-card"><div class="form-grid"><label>流程名称<input v-model="config.name" :disabled="locked" maxlength="100" /></label><label>说明<input v-model="config.description" :disabled="locked" placeholder="说明这套流程用于什么业务" /></label></div></section>
      <section v-if="!locked" class="card ai-panel"><div class="section-heading"><div><h2>AI 辅助配置</h2><p class="subtle">描述字段含义或转换要求，生成待确认的规则草稿。</p></div><span v-if="selected.payload.ai_model" class="subtle">{{ selected.payload.ai_model }}</span></div><textarea v-model="instructions" rows="2" placeholder="例如：货号必须保留前导零；市场价是元，最终销售价取原值，不自动加价。" maxlength="6000"></textarea><div class="form-footer"><span class="subtle">AI 建议不会直接发布，保存和试运行后才能用于新任务。</span><button class="btn" :disabled="busy" @click="run(learn)">✦ 生成 AI 建议</button></div></section>
      <details v-if="selected.payload.notes?.length" class="card notes-panel" open><summary>解析依据与待确认事项（{{ selected.payload.notes.length }}）</summary><ul><li v-for="(note,i) in selected.payload.notes" :key="i">{{ note }}</li></ul></details>
      <div class="section-tabs"><button v-for="item in [{id:'fields',name:'维护字段'},{id:'import',name:'导入规则'},{id:'output',name:'输出方案'},{id:'test',name:'试运行与发布'}]" :key="item.id" :class="{active: tab === item.id}" @click="tab = item.id">{{ item.name }}</button><span class="toolbar-spacer"></span><button v-if="!locked" @click="advanced = JSON.stringify(config, null, 2); advancedOpen = !advancedOpen">高级配置</button></div>
      <section v-if="advancedOpen" class="card"><h2>高级 JSON 配置</h2><textarea v-model="advanced" class="code-editor" spellcheck="false" aria-label="高级JSON配置"></textarea><div class="form-footer"><span class="subtle">修改会在保存时经过后端严格校验。</span><button class="btn" @click="applyAdvanced">应用到编辑器</button></div></section>
      <section v-if="tab === 'fields'" class="card"><div class="section-heading"><h2>标准维护字段 <small>{{ config.fields.length }}</small></h2><button v-if="!locked" class="btn" @click="addField">＋ 添加字段</button></div><div class="table-scroll"><table class="data-table config-table"><thead><tr><th>显示名称</th><th>类型</th><th>必填</th><th>可编辑</th><th>默认值</th><th>更多规则</th><th></th></tr></thead><tbody><tr v-for="(field,i) in config.fields" :key="i"><td><input v-model="field.rule.title" :disabled="locked" aria-label="字段显示名称" /><span class="cell-sub">{{ field.rule.name }}</span></td><td><select v-model="field.rule.type" :disabled="locked" aria-label="字段类型"><option value="string">文本</option><option value="decimal">小数 / 金额</option><option value="integer">整数</option><option value="date">日期</option><option value="datetime">日期时间</option><option value="boolean">是 / 否</option><option value="enum">枚举</option><option value="set">多值集合</option><option value="json">JSON</option></select></td><td><input v-model="field.rule.required" type="checkbox" :disabled="locked" :aria-label="`${field.rule.title}必填`" /></td><td><input v-model="field.editable" type="checkbox" :disabled="locked" :aria-label="`${field.rule.title}可编辑`" /></td><td><input v-model="field.default" :disabled="locked" aria-label="默认值" /></td><td><details><summary>字段规则</summary><div class="field-options"><label>表头别名（逗号分隔）<input :value="field.rule.aliases.join(',')" :disabled="locked" @change="field.rule.aliases = split(($event.target as HTMLInputElement).value)" /></label><label v-if="field.rule.type === 'enum'">允许值（逗号分隔）<input :value="field.rule.enum_values.join(',')" :disabled="locked" @change="field.rule.enum_values = split(($event.target as HTMLInputElement).value)" /></label><template v-if="['integer','decimal'].includes(field.rule.type)"><label>最小值<input v-model="field.rule.validation.min" :disabled="locked" /></label><label>最大值<input v-model="field.rule.validation.max" :disabled="locked" /></label></template><label class="inline-check"><input v-model="field.rule.validation.unique" type="checkbox" :disabled="locked" />字段值唯一</label><label class="inline-check"><input v-model="field.rule.sensitive" type="checkbox" :disabled="locked" />敏感字段，不发送 AI 样例</label></div></details></td><td><button v-if="!locked" class="icon-button" aria-label="删除字段" @click="config.fields.splice(i,1)">×</button></td></tr></tbody></table></div><div class="form-grid extra-settings"><label>业务唯一键（可多选）<select v-model="config.unique_key" multiple :disabled="locked"><option v-for="field in config.fields" :key="field.rule.name" :value="field.rule.name">{{ field.rule.title }}</option></select><small>未配置时不会自动去重。系统记录标识独立于业务唯一键。</small></label><label class="inline-check"><input v-model="config.preserve_extras" type="checkbox" :disabled="locked" />保留原表中未映射的扩展字段</label></div>
        <details class="cross-checks"><summary>跨字段校验</summary><div v-for="(check,i) in config.cross_checks" :key="i" class="toolbar"><select v-model="check.kind" :disabled="locked"><option value="less_equal">左值不大于右值</option><option value="conditional_required">条件必填</option></select><select v-model="check.left" :disabled="locked"><option v-for="field in config.fields" :key="field.rule.name" :value="field.rule.name">{{ field.rule.title }}</option></select><input v-if="check.kind === 'conditional_required'" v-model="check.equals" :disabled="locked" placeholder="等于此值时" /><select v-model="check.right" :disabled="locked"><option v-for="field in config.fields" :key="field.rule.name" :value="field.rule.name">{{ field.rule.title }}</option></select><input v-model="check.message" :disabled="locked" placeholder="错误提示" /><button v-if="!locked" class="icon-button" @click="config.cross_checks.splice(i,1)">×</button></div><button v-if="!locked" class="btn" @click="config.cross_checks.push({kind:'conditional_required',left:config.fields[0].rule.name,right:config.fields[0].rule.name,equals:'',message:'请补充条件必填字段'})">＋ 添加校验</button></details>
      </section>
      <section v-if="tab === 'import'" class="card"><div class="section-heading"><div><h2>从原表进入维护表</h2><p class="subtle">默认按名称和别名匹配。需要换算、拆分或拼接时，在这里添加规则。</p></div><button v-if="!locked" class="btn" @click="config.import_rules.push({field:config.fields[0].rule.name,headers:[],operation:'copy',argument:'',part:0})">＋ 添加规则</button></div><div v-if="!config.import_rules.length" class="empty-state"><h3>使用字段名称与别名自动匹配</h3><p>无需转换的字段不必逐条配置。</p></div><div v-for="(rule,i) in config.import_rules" :key="i" class="rule-card"><div class="form-grid"><label>来源表头（逗号分隔）<input :value="rule.headers.join(',')" :disabled="locked" @change="rule.headers = split(($event.target as HTMLInputElement).value)" /></label><label>目标维护字段<select v-model="rule.field" :disabled="locked"><option v-for="field in config.fields" :key="field.rule.name" :value="field.rule.name">{{ field.rule.title }}</option></select></label><label>转换方式<select v-model="rule.operation" :disabled="locked"><option v-for="op in operations" :key="op.value" :value="op.value">{{ op.label }}</option><option value="trim">去除首尾空格</option></select></label><label v-if="!['copy','trim'].includes(rule.operation)">系数 / 固定值 / 分隔符<input v-model="rule.argument" :disabled="locked" /></label><label v-if="rule.operation === 'split'">取第几段（从 0 开始）<input v-model.number="rule.part" type="number" min="0" :disabled="locked" /></label></div><button v-if="!locked" class="btn text danger" @click="config.import_rules.splice(i,1)">移除此规则</button></div></section>
      <section v-if="tab === 'output'" class="output-config"><article v-for="(output,f) in config.outputs" :key="f" class="card"><div class="section-heading"><label>输出文件名<input v-model="output.name" :disabled="locked" /></label><button v-if="!locked && config.outputs.length > 1" class="btn text danger" @click="config.outputs.splice(f,1)">移除文件</button></div><article v-for="(sheet,s) in output.sheets" :key="s" class="sheet-config"><div class="form-grid"><label>工作表名称<input v-model="sheet.name" :disabled="locked" /></label><label>按字段拆分工作表<select v-model="sheet.group_by" :disabled="locked"><option value="">不拆分</option><option v-for="field in config.fields" :key="field.rule.name" :value="field.rule.name">{{ field.rule.title }}</option></select></label><label>表头行<input v-model.number="sheet.header_row" type="number" min="1" max="50" :disabled="locked" /></label><label>数据起始行<input v-model.number="sheet.data_start_row" type="number" min="2" max="100" :disabled="locked" /></label></div><div class="table-scroll"><table class="data-table config-table"><thead><tr><th>输出列名</th><th>维护字段</th><th>转换</th><th>参数</th><th>必填</th><th></th></tr></thead><tbody><tr v-for="(column,c) in sheet.columns" :key="c"><td><input v-model="column.title" :disabled="locked" /></td><td><select v-model="column.field" :disabled="locked || ['constant','formula','concat'].includes(column.operation)"><option value="">请选择字段</option><option v-for="field in config.fields" :key="field.rule.name" :value="field.rule.name">{{ field.rule.title }}</option></select><select v-if="column.operation === 'concat'" v-model="column.sources" multiple :disabled="locked"><option v-for="field in config.fields" :key="field.rule.name" :value="field.rule.name">{{ field.rule.title }}</option></select></td><td><select v-model="column.operation" :disabled="locked"><option v-for="op in operations" :key="op.value" :value="op.value">{{ op.label }}</option><option value="formula">Excel 公式</option></select></td><td><input v-if="column.operation !== 'copy'" v-model="column.argument" :disabled="locked" :placeholder="column.operation === 'formula' ? '=A{row}*B{row}' : '系数 / 分隔符 / 固定值'" /><input v-if="column.operation === 'split'" v-model.number="column.part" type="number" min="0" :disabled="locked" /><input v-model="column.number_format" placeholder="显示格式（可选）" :disabled="locked" /></td><td><input v-model="column.required" type="checkbox" :disabled="locked" /></td><td><button v-if="!locked" class="icon-button" aria-label="上移输出列" :disabled="c === 0" @click="sheet.columns.splice(c-1,0,sheet.columns.splice(c,1)[0])">↑</button><button v-if="!locked" class="icon-button" aria-label="删除输出列" @click="sheet.columns.splice(c,1)">×</button></td></tr></tbody></table></div><div class="form-footer"><button v-if="!locked" class="btn" @click="sheet.columns.push(newColumn(config.fields[0].rule.name))">＋ 添加输出列</button><button v-if="!locked && output.sheets.length > 1" class="btn text danger" @click="output.sheets.splice(s,1)">移除工作表</button></div><details><summary>SKU 展开设置</summary><div class="form-grid"><label>规格维度（可多选，按笛卡尔积展开）<select v-model="sheet.sku_fields" multiple :disabled="locked"><option v-for="field in config.fields" :key="field.rule.name" :value="field.rule.name">{{ field.rule.title }}</option></select></label><label>多值分隔符<input v-model="sheet.sku_separator" :disabled="locked" /></label></div></details></article><button v-if="!locked" class="btn" @click="output.sheets.push({name:`工作表${output.sheets.length+1}`,header_row:1,data_start_row:2,columns:[newColumn(config.fields[0].rule.name,'商品名称')],group_by:'',sku_fields:[],sku_separator:'|'})">＋ 添加工作表</button></article><button v-if="!locked" class="btn" @click="config.outputs.push({name:`输出文件${config.outputs.length+1}.xlsx`,sheets:[{name:'商品表',header_row:1,data_start_row:2,columns:[newColumn(config.fields[0].rule.name,'商品名称')],group_by:'',sku_fields:[],sku_separator:'|'}]})">＋ 添加输出文件</button></section>
      <section v-if="tab === 'test'" class="card"><h2>用真实样例验证模板</h2><p class="subtle">上传一份原始数据样例，检查字段校验及生成结果。模板自带数据时，也可直接试运行。</p><div v-if="!locked" class="toolbar"><label class="btn file-button">{{ sample?.name || '选择原始数据样例' }}<input type="file" accept=".xlsx" @change="sample = ($event.target as HTMLInputElement).files?.[0]" /></label><button class="btn" :disabled="busy" @click="run(trial)">执行试运行</button><button class="btn text" @click="run(() => download('/workflow-examples/source', '商品原表样例.xlsx'))">下载示例原表</button></div><div v-if="selected.payload.test_result" class="trial-result"><div class="notice" :class="selected.payload.test_result.passed ? 'success' : 'error'">{{ selected.payload.test_result.passed ? '试运行通过' : '试运行未通过' }} · {{ selected.payload.test_result.records }} 条样例 · {{ selected.payload.test_result.errors }} 个问题</div><p v-for="(issue,i) in selected.payload.test_result.issues" :key="i" class="danger">第 {{ issue.row }} 条 / {{ issue.field }}：{{ issue.message }}</p><div class="toolbar"><button v-for="(artifact,i) in selected.payload.test_result.artifacts" :key="i" class="btn" @click="run(() => download(`/workflow-templates/${id}/trial/${i}`, artifact.name))">查看试运行结果：{{ artifact.name }}</button></div></div><div v-if="!locked" class="publish-panel"><label class="inline-check"><input v-model="confirmed" type="checkbox" />我已确认字段映射、业务规则和输出结构</label><p class="subtle">发布后新任务可选用此版本；已有任务继续使用其原版本。</p><button class="btn primary" :disabled="busy || !confirmed || !selected.payload.tested_hash" @click="run(publish)">发布模板版本</button></div></section>
      <div v-if="!locked" class="sticky-actions"><span>{{ dirty ? '有未保存的配置修改' : '配置已保存' }}</span><div class="toolbar"><button class="btn" :disabled="busy" @click="run(save)">保存草稿</button><button class="btn primary" :disabled="busy" @click="tab = 'test'">前往试运行 →</button></div></div>
    </template>
  </template>
</template>
